import java.util.*;

/**
 * Created by naveen on 19-Dec-15.
 */
public class test {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int n = Integer.parseInt(sc.nextLine());
        String line = sc.nextLine();

        int braceWordCount = 0;
        int maxWordLen = 0;

        boolean insideParentheses = false;

        StringBuilder buffer = new StringBuilder();

        for (int i = 0; i < n; i++) {
            char c = line.charAt(i);

            if (c == '_') {
                updateCounts(buffer, insideParentheses, (len) -> {
                    if (len > 0) {
                        if (insideParentheses) {
                            braceWordCount++;
                        } else {
                            maxWordLen = Math.max(maxWordLen, len);
                        }
                    }
                });
                buffer = new StringBuilder();
            } else if (c == '(') {
                updateCounts(buffer, insideParentheses, (len) -> {
                    if (len > 0) {
                        if (insideParentheses) {
                            braceWordCount++;
                        } else {
                            maxWordLen = Math.max(maxWordLen, len);
                        }
                    }
                });
                buffer = new StringBuilder();
                insideParentheses = true;
            } else if (c == ')') {
                updateCounts(buffer, insideParentheses, (len) -> {
                    if (len > 0) {
                        if (insideParentheses) {
                            braceWordCount++;
                        } else {
                            maxWordLen = Math.max(maxWordLen, len);
                        }
                    }
                });
                buffer = new StringBuilder();
                insideParentheses = false;
            } else if (Character.isLetter(c)) {
                buffer.append(c);
            }
        }

        updateCounts(buffer, insideParentheses, (len) -> {
            if (len > 0) {
                if (insideParentheses) {
                    braceWordCount++;
                } else {
                    maxWordLen = Math.max(maxWordLen, len);
                }
            }
        });

        System.out.println(maxWordLen + " " + braceWordCount);
    }

    private static void updateCounts(StringBuilder buf, boolean inBraces, java.util.function.IntConsumer consumer) {
        int length = buf.length();
        if (length > 0) {
            consumer.accept(length);
        }
    }
}
